insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort) values
  ('ARC-M01', 'Movilidad', 'Cardio suave', 'Cuerpo entero', 'Bici, elíptica o cinta', '5 minutos a ritmo cómodo en bici, elíptica o cinta inclinada, hasta notar calor en el cuerpo.', 'Tienes que poder hablar sin ahogarte. Es para calentar, no para cansarte.', '', '', '', 80), 
  ('ARC-M02', 'Movilidad', 'Cadera 90/90', 'Cadera', 'Suelo', 'Sentada en el suelo con las dos rodillas dobladas a 90 grados, giras las piernas de un lado a otro sin usar las manos.', 'Mantén el pecho alto. Haz 6-8 cambios lentos por lado.', '', '', '', 81), 
  ('ARC-M03', 'Movilidad', 'Gato-camello', 'Columna', 'Suelo', 'A cuatro patas, redondeas la espalda llevando la barbilla al pecho y luego la arqueas mirando al frente.', 'Muévete vértebra a vértebra y respira: sube al soltar el aire. 8-10 repeticiones.', '', '', '', 82), 
  ('ARC-M04', 'Movilidad', 'Rotación torácica a cuatro patas', 'Espalda alta', 'Suelo', 'A cuatro patas con una mano en la nuca, giras el codo hacia el techo y luego lo bajas hacia la otra mano.', 'La cadera no se mueve: gira solo la parte de arriba de la espalda. 6-8 por lado.', '', '', '', 83), 
  ('ARC-M05', 'Movilidad', 'Movilidad de tobillo en la pared', 'Tobillo', 'Pared', 'Con un pie a un palmo de la pared, llevas la rodilla hacia delante hasta tocarla sin levantar el talón.', 'Si llegas fácil, aleja un poco el pie. Clave para bajar más en la sentadilla. 8-10 por lado.', '', '', '', 84), 
  ('ARC-M06', 'Movilidad', 'Puente de glúteo', 'Glúteo', 'Suelo', 'Tumbada boca arriba con las rodillas dobladas, subes la cadera apretando el glúteo y bajas despacio.', 'Aguanta 2 segundos arriba. 12-15 repeticiones para despertar el glúteo antes de pierna.', '', '', '', 85), 
  ('ARC-M07', 'Movilidad', 'Monster walk con banda', 'Glúteo medio', 'Banda elástica', 'Con una banda encima de las rodillas y semiflexionada, das pasos laterales y en diagonal sin juntar los pies.', 'Las rodillas siempre hacia fuera. 10-12 pasos hacia cada lado.', '', '', '', 86), 
  ('ARC-M08', 'Movilidad', 'Pase de hombros con palo o banda', 'Hombro', 'Palo o banda', 'De pie con un palo o banda agarrado muy abierto, lo pasas por encima de la cabeza hasta detrás y vuelves.', 'Brazos estirados. Si no pasa, abre más el agarre. 10 repeticiones lentas.', '', '', '', 87), 
  ('ARC-M09', 'Movilidad', 'Face pull con banda', 'Hombro y espalda alta', 'Banda elástica', 'Con una banda enganchada a la altura de la cara, tiras hacia ti separando las manos y abriendo los codos.', 'Peso muy ligero: es activación. 15 repeticiones antes de torso.', '', '', '', 88), 
  ('ARC-M10', 'Movilidad', 'Sentadilla profunda con apoyo', 'Cadera y tobillo', 'Mancuerna o peso corporal', 'Bajas a una sentadilla profunda sujetando una mancuerna ligera delante del pecho y te quedas abajo moviendo la cadera.', 'Empuja las rodillas hacia fuera con los codos. Quédate 30-45 segundos abajo.', '', '', '', 89), 
  ('ARC-M11', 'Movilidad', 'Estiramiento de flexor de cadera', 'Cadera', 'Suelo', 'En zancada con la rodilla de atrás apoyada, llevas la cadera hacia delante apretando el glúteo de esa pierna.', 'Mejor al final o en días libres. 30-45 segundos por lado, respirando.', '', '', '', 90), 
  ('ARC-M12', 'Movilidad', 'Estiramiento de pectoral en la pared', 'Pecho y hombro', 'Pared', 'Con el antebrazo apoyado en una pared o marco de puerta, giras el cuerpo hacia el lado contrario.', 'Notas el estiramiento en el pecho, no dolor en el hombro. 30 segundos por lado.', '', '', '', 91)
